def solve(x):
    items = []; out = []
    for c in x["commands"]:
        if c["op"] == "push":
            if len(items) < x["capacity"]:
                items.append(c["value"])
                out.append(None)
            else:
                out.append(None)
        elif c["op"] == "pop":
            out.append(items.pop(0) if items else None)
        else:
            out.append(items[0] if items else None)
    return out
